<script setup lang="ts">
import { ElAlert, ElButton, ElCheckbox, ElEmpty, ElInput, ElOption, ElProgress, ElSelect, ElTable, ElTableColumn, ElTag, vLoading, ElMessageBox } from 'element-plus'
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { api,errorText } from '../api/client'
import { statusLabels,roleLabels,predictionSourceLabels } from '../types'
import type { User,Group,Category,FAQ,Stats,Role,TicketStatus } from '../types'
const route=useRoute(),section=computed(()=>String(route.params.section||'stats')),error=ref(''),busy=ref(false),loading=ref(false),success=ref(''),editing=ref<number|null>(null),showForm=ref(false)
const users=ref<User[]>([]),groups=ref<Group[]>([]),categories=ref<Category[]>([]),faqs=ref<FAQ[]>([]),stats=ref<Stats|null>(null)
const tabs=[{key:'stats',label:'运行统计'},{key:'users',label:'账号管理'},{key:'groups',label:'客服组'},{key:'categories',label:'分类与路由'},{key:'faqs',label:'知识管理'}]
const form=reactive({username:'',display_name:'',password:'',role:'user' as Role,active:true,group_id:null as number|null,name:'',keywords:'',question:'',answer:'',category_id:null as number|null})
type AdminRow=Partial<User & Category & FAQ> & {id:number;name?:string}
const rows=computed<AdminRow[]>(() => section.value==='users'?users.value:section.value==='groups'?groups.value:section.value==='categories'?categories.value:faqs.value)
const title=computed(()=>tabs.find(t=>t.key===section.value)?.label||'运行统计')
function edit(row?:AdminRow){editing.value=row?.id??null;Object.assign(form,{username:'',display_name:'',password:'',role:'user',active:true,group_id:null,name:'',keywords:'',question:'',answer:'',category_id:null},row??{});showForm.value=true;error.value='';success.value=''}
let loadId=0, sectionId=0
async function load(){const id=++loadId;loading.value=true;error.value='';try{const results=await Promise.all([api<User[]>('/admin/users'),api<Group[]>('/admin/groups'),api<Category[]>('/admin/categories'),api<FAQ[]>('/admin/faqs'),api<Stats>('/admin/stats')]);if(id===loadId)[users.value,groups.value,categories.value,faqs.value,stats.value]=results}catch(e){if(id===loadId)error.value=errorText(e)}finally{if(id===loadId)loading.value=false}}
async function save(){if(busy.value)return;error.value='';success.value='';let payload:Record<string,unknown>
if(section.value==='users'){if(!form.display_name.trim()||(!editing.value&&!/^[A-Za-z0-9_.-]{3,40}$/.test(form.username))||((!editing.value||form.password)&& (form.password.length<12||form.password.length>128))){error.value='请填写姓名、有效账号（3–40 位字母数字及 _ . -）和 12–128 位密码';return}payload={display_name:form.display_name.trim(),role:form.role,active:form.active,group_id:form.role==='agent'?form.group_id:null,...(!editing.value?{username:form.username,password:form.password}:form.password?{password:form.password}:{})}}
else if(section.value==='groups'){if(!form.name.trim()){error.value='请填写客服组名称';return}payload={name:form.name.trim()}}
else if(section.value==='categories'){if(!form.name.trim()){error.value='请填写分类名称';return}payload={name:form.name.trim(),keywords:form.keywords,active:form.active,group_id:form.group_id}}
else{if(!form.question.trim()||!form.answer.trim()){error.value='请填写知识问题和答案';return}payload={question:form.question.trim(),answer:form.answer.trim(),keywords:form.keywords,category_id:form.category_id,active:form.active}}
const id=sectionId;busy.value=true;try{await api('/admin/'+section.value+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:payload});if(id!==sectionId)return;showForm.value=false;success.value='保存成功';await load()}catch(e){if(id===sectionId)error.value=errorText(e)}finally{if(id===sectionId)busy.value=false}}
async function removeFaq(row:{id:number}){const id=sectionId;try{await ElMessageBox.confirm('将永久删除此知识条目，已有工单不受影响。','删除知识条目',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'})}catch{return}if(id!==sectionId)return;busy.value=true;error.value='';try{await api('/admin/faqs/'+row.id,{method:'DELETE'});if(id!==sectionId)return;success.value='知识条目已删除';await load()}catch(e){if(id===sectionId)error.value=errorText(e)}finally{if(id===sectionId)busy.value=false}}
function percentage(count:number){return stats.value?.total?Math.round(count/stats.value.total*100):0}
onMounted(load);watch(section,()=>{++sectionId;busy.value=false;showForm.value=false;error.value='';success.value='';void load()})
</script>
<template><div class="admin-page"><div class="page-heading"><div><h1>系统管理</h1><p>维护账号、服务路由和本地知识，查看实际工单分布。</p></div><ElButton :loading="loading" @click="load">刷新数据</ElButton></div><nav class="admin-tabs" aria-label="管理导航"><RouterLink v-for="tab in tabs" :key="tab.key" :to="'/staff/admin/'+tab.key" :class="{active:section===tab.key}">{{tab.label}}</RouterLink></nav><ElAlert v-if="error" :title="error" type="error" :closable="false"/><ElAlert v-if="success" :title="success" type="success" :closable="false"/><div v-loading="loading"><template v-if="section==='stats'"><div v-if="stats" class="stats-grid"><section class="stat"><span>工单总数</span><strong>{{stats.total}}</strong></section><section class="stat"><span>待分配工单</span><strong>{{stats.unassigned}}</strong><RouterLink v-if="stats.unassigned" :to="{path:'/staff/tickets',query:{scope:'queue',status:'pending'}}">查看待分配</RouterLink></section><section class="stat"><span>人工分类纠错</span><strong>{{stats.corrections}}</strong></section></div><div v-if="stats" class="stats-charts"><section v-for="chart in [{title:'处理状态',values:stats.by_status},{title:'问题分类',values:stats.by_category},{title:'分类来源',values:stats.by_source}]" :key="chart.title" class="panel"><h2>{{chart.title}}</h2><ElEmpty v-if="!chart.values.length" description="暂无工单数据" :image-size="50"/><div v-for="item in chart.values" :key="item.name" class="chart-row"><div><span>{{(chart.title==='分类来源' ? predictionSourceLabels[item.name] : chart.title==='处理状态' ? statusLabels[item.name as TicketStatus] : null)||item.name}}</span><strong>{{item.count}}</strong></div><ElProgress :percentage="percentage(item.count)" :show-text="false" :stroke-width="10"/></div></section></div></template><section v-else class="panel"><div class="title-row"><h2>{{title}}</h2><ElButton type="primary" :disabled="busy" @click="edit()">新增{{section==='users'?'账号':section==='groups'?'客服组':section==='categories'?'分类':'知识'}}</ElButton></div><p v-if="section==='categories'" class="muted">分类绑定客服组即为路由规则。停用分类后不会用于新的自动分配。</p><div class="table-scroll"><ElTable :data="rows" empty-text="暂无记录，请新增"><ElTableColumn prop="id" label="ID" width="65"/><template v-if="section==='users'"><ElTableColumn prop="username" label="账号" min-width="120"/><ElTableColumn prop="display_name" label="姓名" min-width="100"/><ElTableColumn label="角色" width="90"><template #default="{row}">{{roleLabels[row.role as Role]}}</template></ElTableColumn></template><ElTableColumn v-if="section==='groups'||section==='categories'" prop="name" label="名称" min-width="140"/><ElTableColumn v-if="section==='faqs'" prop="question" label="问题" min-width="230" show-overflow-tooltip/><ElTableColumn v-if="section==='faqs'||section==='categories'" prop="keywords" label="匹配关键词" min-width="150" show-overflow-tooltip/><ElTableColumn v-if="section==='categories'||section==='users'" label="客服组 / 路由" min-width="140"><template #default="{row}">{{groups.find(g=>g.id===row.group_id)?.name||'未绑定'}}</template></ElTableColumn><ElTableColumn v-if="section!=='groups'" label="状态" width="90"><template #default="{row}"><ElTag :type="row.active?'success':'info'">{{row.active?'启用':'停用'}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" min-width="150"><template #default="{row}"><ElButton text type="primary" :disabled="busy" @click="edit(row as AdminRow)">编辑</ElButton><ElButton v-if="section==='faqs'" text type="danger" :disabled="busy" @click="removeFaq(row as AdminRow)">删除</ElButton></template></ElTableColumn></ElTable></div><section v-if="showForm" class="editor"><h2>{{editing?'编辑 #'+editing:'新增记录'}}</h2><form @submit.prevent="save"><template v-if="section==='users'"><label for="admin-username">账号</label><ElInput id="admin-username" v-model="form.username" :disabled="!!editing" maxlength="40"/><label for="display-name">显示姓名</label><ElInput id="display-name" v-model="form.display_name" maxlength="80"/><label for="admin-password">{{editing?'重设密码（留空保持原密码）':'初始密码（12–128 位）'}}</label><ElInput id="admin-password" v-model="form.password" type="password" show-password autocomplete="new-password" maxlength="128"/><label for="role">角色</label><ElSelect id="role" v-model="form.role"><ElOption v-for="(label,key) in roleLabels" :key="key" :label="label" :value="key"/></ElSelect><p class="muted">停用、改角色或重设密码会撤销该账号的当前登录。用户有未关闭工单时需先完成工单再改角色。</p></template><template v-if="section==='groups'||section==='categories'"><label for="name">名称</label><ElInput id="name" v-model="form.name" maxlength="80"/></template><template v-if="section==='categories'||section==='users'&&form.role==='agent'"><label for="group">{{section==='categories'?'路由目标客服组':'所属客服组'}}</label><ElSelect id="group" v-model="form.group_id" clearable :value-on-clear="null" placeholder="不绑定客服组"><ElOption v-for="group in groups" :key="group.id" :label="group.name" :value="group.id"/></ElSelect></template><template v-if="section==='faqs'"><label for="faq-question">问题</label><ElInput id="faq-question" v-model="form.question" maxlength="300"/><label for="faq-answer">答案</label><ElInput id="faq-answer" v-model="form.answer" type="textarea" :rows="6" maxlength="10000"/><label for="faq-category">所属分类</label><ElSelect id="faq-category" v-model="form.category_id" clearable :value-on-clear="null"><ElOption v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></ElSelect></template><template v-if="section==='faqs'||section==='categories'"><label for="keywords">匹配关键词（逗号分隔）</label><ElInput id="keywords" v-model="form.keywords" maxlength="1000"/></template><div class="actions"><ElCheckbox v-if="section!=='groups'" v-model="form.active">启用</ElCheckbox><ElButton native-type="submit" type="primary" :loading="busy">保存</ElButton><ElButton :disabled="busy" @click="showForm=false">取消</ElButton></div></form></section></section></div></div></template>
